from pathlib import Path
p=Path('app/admin.tsx');s=p.read_text()
old="{key:'settings',title:'إعدادات التطبيق',subtitle:'الخصوصية والخدمات والتحكم العام',icon:'settings-outline'},"
new=old+"\n            {key:'aiControl',title:'مركز تحكم AI',subtitle:'توليد ومراجعة الأسئلة',icon:'sparkles-outline'},\n            {key:'gameControl',title:'تحكم الألعاب',subtitle:'التحديات والـStreak والمتصدرين',icon:'game-controller-outline'},\n            {key:'analytics',title:'تحليلات Wanas',subtitle:'نشاط الألعاب وAI والمستخدمين',icon:'bar-chart-outline'},"
if old in s and "key:'aiControl'" not in s:s=s.replace(old,new,1)
anchor='              return <><Back/><SectionHeader title="إعدادات التطبيق" icon="settings-outline"/>'
branches='''              if(tab==='aiControl')return <><Back/><SectionHeader title="مركز تحكم AI" icon="sparkles-outline"/><View style={styles.card}><Text style={styles.h2}>بنك الأسئلة</Text><Text style={styles.health}>إجمالي: {aiQuestions.length}</Text><Text style={styles.health}>معتمدة: {aiQuestions.filter((x:any)=>x.status==='approved').length}</Text><Text style={styles.health}>مستبعدة: {aiQuestions.filter((x:any)=>x.status==='rejected').length}</Text><Text style={styles.health}>تشغيلات AI: {aiRuns.length}</Text></View><View style={styles.card}><Text style={styles.h2}>آخر الأسئلة</Text>{aiQuestions.slice(0,12).map((q:any)=><Text key={q.id} style={styles.log}>{q.subject} • {q.difficulty||'medium'} • {q.status}</Text>)}</View></>;
              if(tab==='gameControl')return <><Back/><SectionHeader title="تحكم الألعاب" icon="game-controller-outline"/><View style={styles.card}><Text style={styles.h2}>غرف التحديات</Text><Text style={styles.health}>الإجمالي: {challengeRooms.length}</Text><Text style={styles.health}>انتظار: {challengeRooms.filter((x:any)=>x.status==='waiting').length}</Text><Text style={styles.health}>نشطة: {challengeRooms.filter((x:any)=>x.status==='active').length}</Text><Text style={styles.health}>منتهية: {challengeRooms.filter((x:any)=>x.status==='finished').length}</Text></View></>;
              if(tab==='analytics')return <><Back/><SectionHeader title="تحليلات Wanas" icon="bar-chart-outline"/><View style={styles.stats}>{[['people','المستخدمون',counts.users],['game-controller','غرف الألعاب',challengeRooms.length],['sparkles','أسئلة AI',aiQuestions.length],['headset','شكاوى',counts.open]].map(([ic,t,v])=><View style={styles.stat} key={String(t)}><Ionicons name={ic as any} size={22} color="#77a2ff"/><Text style={styles.statValue}>{String(v)}</Text><Text style={styles.statLabel}>{String(t)}</Text></View>)}</View><View style={styles.card}><Text style={styles.h2}>آخر تشغيلات AI</Text>{aiRuns.slice(0,20).map((x:any)=><Text key={x.id} style={styles.log}>{x.subject} • {x.count_generated}/{x.count_requested} • {x.status}</Text>)}</View></>;
'''
if anchor in s and "if(tab==='aiControl')" not in s:s=s.replace(anchor,branches+anchor,1)
p.write_text(s)
